"use client";

/**
 * Optional UI sound (off by default). Howler is imported lazily the first
 * time sound is switched on, so it costs nothing for visitors who never do.
 * The WAVs are generated by scripts/generate-assets.mjs.
 */
import type { Howl as HowlType } from "howler";

type SoundName = "tick" | "key" | "hum" | "whoosh";
let sounds: Partial<Record<SoundName, HowlType>> = {};
let enabled = false;
let loading: Promise<void> | null = null;

async function load() {
  if (loading) return loading;
  loading = (async () => {
    const { Howl } = await import("howler");
    sounds = {
      tick: new Howl({ src: ["/sounds/tick.wav"], volume: 0.25 }),
      key: new Howl({ src: ["/sounds/key.wav"], volume: 0.12 }),
      whoosh: new Howl({ src: ["/sounds/whoosh.wav"], volume: 0.18 }),
      hum: new Howl({ src: ["/sounds/hum.wav"], volume: 0.08, loop: true }),
    };
  })();
  return loading;
}

export async function setSoundEnabled(on: boolean) {
  enabled = on;
  if (on) {
    await load();
    if (enabled && !sounds.hum?.playing()) sounds.hum?.play();
    sounds.hum?.fade(0, 0.08, 800);
  } else {
    sounds.hum?.fade(0.08, 0, 300);
    setTimeout(() => !enabled && sounds.hum?.stop(), 320);
  }
}

let lastKey = 0;
export function playSound(name: Exclude<SoundName, "hum">) {
  if (!enabled) return;
  if (name === "key") {
    const now = performance.now();
    if (now - lastKey < 35) return;
    lastKey = now;
    sounds.key?.rate(0.9 + Math.random() * 0.25);
  }
  sounds[name]?.play();
}
